begin;
create table zoi.intelligence_receipts(id uuid primary key default gen_random_uuid(),token_hash text not null unique check(token_hash~'^[a-f0-9]{64}$'),client_hash text not null check(client_hash~'^[a-f0-9]{64}$'),report jsonb not null check(octet_length(report::text)<=24000),created_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '2 hours',claimed_workspace uuid references zoi.workspaces(id),claimed_profile uuid references zoi.user_profiles(id),claimed_report uuid);
create index intelligence_receipts_expiry on zoi.intelligence_receipts(expires_at);
create index intelligence_receipts_client_time on zoi.intelligence_receipts(client_hash,created_at);
create table zoi.intelligence_reports(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references zoi.workspaces(id),listing_id uuid not null references zoi.listings(id),saved_by uuid not null references zoi.user_profiles(id),receipt_id uuid not null unique,report jsonb not null check(octet_length(report::text)<=24000),saved_at timestamptz not null default now());
create index intelligence_reports_workspace_time on zoi.intelligence_reports(workspace_id,saved_at desc,id desc);
alter table zoi.intelligence_receipts enable row level security;alter table zoi.intelligence_reports enable row level security;
revoke all on zoi.intelligence_receipts,zoi.intelligence_reports from public,anon,authenticated;
create function zoi.intelligence_operator(p_workspace uuid)returns uuid language plpgsql security definer set search_path='' as $$declare a uuid;begin select id into a from zoi.user_profiles where auth_user_id=auth.uid();perform 1 from zoi.workspace_members where workspace_id=p_workspace and profile_id=a and role in('owner','admin')for share;if not found then raise exception 'intelligence_owner_admin_required' using errcode='42501';end if;return a;end$$;
create function zoi.intelligence_host(p_url text)returns text language sql immutable set search_path='' as $$select lower(regexp_replace(substring(p_url from '^https?://([^/:?#]+)'),'^www\.','','i'))$$;
create function public.intelligence_receipt_store(p_token_hash text,p_client_hash text,p_report jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare r zoi.intelligence_receipts;begin
if p_token_hash is null or p_token_hash!~'^[a-f0-9]{64}$' or p_client_hash is null or p_client_hash!~'^[a-f0-9]{64}$' or jsonb_typeof(p_report) is distinct from 'object' or octet_length(p_report::text)>24000 or jsonb_typeof(p_report->'checks') is distinct from 'array' or jsonb_array_length(p_report->'checks') not between 1 and 30 or p_report->>'ok' is distinct from 'true' or p_report->>'mode' is distinct from 'free_test' or zoi.intelligence_host(p_report->>'requested_url') is null or zoi.intelligence_host(p_report->>'url') is null or p_report->>'checked_at' is null or (p_report->>'checked_at')::timestamptz not between now()-interval '5 minutes' and now()+interval '1 minute' then raise exception 'invalid_scan_receipt';end if;
perform pg_advisory_xact_lock(hashtextextended('intelligence_receipt_budget',0));
delete from zoi.intelligence_receipts where id in(select id from zoi.intelligence_receipts where expires_at<now() order by expires_at limit 200);
if (select count(*) from zoi.intelligence_receipts where created_at>now()-interval '1 hour')>=2000 or (select count(*)from zoi.intelligence_receipts where client_hash=p_client_hash and created_at>now()-interval '1 hour')>=20 then raise exception 'receipt_capacity_reached';end if;
insert into zoi.intelligence_receipts(token_hash,client_hash,report)values(p_token_hash,p_client_hash,p_report)returning * into r;return jsonb_build_object('ok',true,'expires_at',r.expires_at);end$$;
create function public.intelligence_report_claim(p_workspace uuid,p_listing uuid,p_token_hash text)returns jsonb language plpgsql security definer set search_path='' as $$declare a uuid;r zoi.intelligence_receipts;s zoi.intelligence_reports;site text;begin a:=zoi.intelligence_operator(p_workspace);
select website into site from zoi.listings where id=p_listing and owner_workspace_id=p_workspace for share;if not found then raise exception 'owned_business_required' using errcode='42501';end if;
select * into r from zoi.intelligence_receipts where token_hash=p_token_hash for update;if not found then raise exception 'report_expired_or_unavailable';end if;
if r.claimed_report is not null then if r.claimed_workspace is distinct from p_workspace or r.claimed_profile is distinct from a then raise exception 'report_already_saved_elsewhere' using errcode='42501';end if;select * into s from zoi.intelligence_reports where id=r.claimed_report and listing_id=p_listing;if not found then raise exception 'report_already_saved_elsewhere';end if;return jsonb_build_object('ok',true,'report',to_jsonb(s),'already_saved',true);end if;
if r.expires_at<=now() then raise exception 'report_expired_or_unavailable';end if;
if zoi.intelligence_host(site) is null or zoi.intelligence_host(site) is distinct from zoi.intelligence_host(r.report->>'requested_url') then raise exception 'report_business_website_mismatch';end if;
insert into zoi.intelligence_reports(workspace_id,listing_id,saved_by,receipt_id,report)values(p_workspace,p_listing,a,r.id,r.report)returning * into s;
update zoi.intelligence_receipts set claimed_workspace=p_workspace,claimed_profile=a,claimed_report=s.id where id=r.id;
return jsonb_build_object('ok',true,'report',to_jsonb(s),'already_saved',false);end$$;
create function public.intelligence_reports_list(p_workspace uuid,p_listing uuid default null,p_offset integer default 0)returns jsonb language plpgsql security definer set search_path='' as $$declare rows jsonb;begin perform zoi.intelligence_operator(p_workspace);if p_offset is null or p_offset<0 or p_offset>5000 then raise exception 'invalid_report_page';end if;select coalesce(jsonb_agg(to_jsonb(r)),'[]')into rows from(select id,workspace_id,listing_id,saved_at,report->>'url' url,report->>'checked_at' checked_at from zoi.intelligence_reports where workspace_id=p_workspace and(p_listing is null or listing_id=p_listing)order by saved_at desc,id desc limit 51 offset p_offset)r;return jsonb_build_object('ok',true,'reports',rows,'offset',p_offset);end$$;
create function public.intelligence_report_get(p_workspace uuid,p_report uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare r zoi.intelligence_reports;begin perform zoi.intelligence_operator(p_workspace);select * into r from zoi.intelligence_reports where workspace_id=p_workspace and id=p_report;if not found then raise exception 'report_not_found';end if;return jsonb_build_object('ok',true,'report',to_jsonb(r));end$$;
revoke all on function zoi.intelligence_operator(uuid),zoi.intelligence_host(text),public.intelligence_receipt_store(text,text,jsonb),public.intelligence_report_claim(uuid,uuid,text),public.intelligence_reports_list(uuid,uuid,integer),public.intelligence_report_get(uuid,uuid) from public,anon,authenticated;
grant execute on function public.intelligence_receipt_store(text,text,jsonb)to service_role;
grant execute on function public.intelligence_report_claim(uuid,uuid,text),public.intelligence_reports_list(uuid,uuid,integer),public.intelligence_report_get(uuid,uuid)to authenticated;
commit;
